items.script:
document.getElementById("flip").addEventListener("click", () => {
  const box = document.getElementById("box");
  box.dir = box.dir === "rtl" ? "ltr" : "rtl";
});

const data = [{ label: "Mon", value: 3 }, { label: "Tue", value: 7 }, { label: "Wed", value: 5 }, { label: "Thu", value: 9 }, { label: "Fri", value: 6 }];
document.getElementById("charts").append(
  components.chart({ type: "bar", data }),
  components.chart({ type: "line", data }),
);

const rows = [
  { name: "photo.png", type: "Image", size: "1.5 MB" },
  { name: "notes.txt", type: "Text", size: "2 KB" },
  { name: "song.mp3", type: "Audio", size: "4.2 MB" },
  { name: "movie.mp4", type: "Video", size: "120 MB" },
  { name: "report.pdf", type: "PDF", size: "800 KB" },
  { name: "logo.svg", type: "Image", size: "6 KB" },
];
document.getElementById("files").append(components.dataTable({
  columns: [{ key: "name", label: "Name" }, { key: "type", label: "Type" }, { key: "size", label: "Size" }],
  rows,
  pageSize: 4,
}).element);

components.select({
  trigger: document.getElementById("fruit"),
  options: [{ value: "apple", label: "Apple" }, { value: "banana", label: "Banana" }, { value: "cherry", label: "Cherry" }],
  value: "banana",
  onChange: (value) => popups.toast(value),
});

autocomplete.attach(document.getElementById("fruit-search"), {
  suggestions: () => ["Apple", "Apricot", "Banana", "Cherry", "Grape"],
});

const button = document.getElementById("pick-date");
button.addEventListener("click", () => {
  const picker = components.calendar({
    onSelect: (date) => {
      button.firstChild.textContent = date.toLocaleDateString();
      components.closeOverlay();
    },
  });
  components.popover({ anchor: button, content: picker.element });
});

document.getElementById("open-menu").addEventListener("click", (event) => {
  components.menu({
    anchor: event.currentTarget,
    items: [
      { label: "Profile", icon: "user", onSelect: () => popups.toast("Profile") },
      { label: "Settings", icon: "sliders", onSelect: () => popups.toast("Settings") },
      { separator: true },
      { label: "Sign out", icon: "logout", danger: true, onSelect: () => popups.toast("Signed out") },
    ],
  });
});

document.getElementById("area").addEventListener("contextmenu", (event) => {
  event.preventDefault();
  components.menu({
    point: { x: event.clientX, y: event.clientY },
    items: [
      { label: "Copy", icon: "copy", onSelect: () => popups.toast("Copied") },
      { label: "Rename", icon: "pencil" },
      { separator: true },
      { label: "Delete", icon: "trash", danger: true },
    ],
  });
});

document.getElementById("open-popover").addEventListener("click", (event) => {
  components.popover({
    anchor: event.currentTarget,
    content: components.element("p", "", "Anything can go in a popover."),
  });
});

const menus = { file: ["New", "Open", "Save"], edit: ["Undo", "Redo"], view: ["Zoom in", "Zoom out"] };
document.querySelectorAll("[data-menu]").forEach((button) => button.addEventListener("click", () => components.menu({
  anchor: button,
  items: menus[button.dataset.menu].map((label) => ({ label, onSelect: () => popups.toast(label) })),
})));

const panels = { start: ["Introduction", "Installation"], parts: ["Button", "Card", "Tabs"], docs: ["Changelog", "Rules"] };
document.querySelectorAll("[data-panel]").forEach((button) => button.addEventListener("click", () => {
  const list = components.element("div", "section-body");
  panels[button.dataset.panel].forEach((name) => list.append(components.element("button", "menu-item", name)));
  components.popover({ anchor: button, content: list });
}));

const thread = document.getElementById("thread");
const follow = components.scroller(thread);
const add = (text) => {
  thread.append(components.element("div", "bubble", text));
  follow.follow();
};
for (let number = 1; number <= 6; number++) add("Message " + number);
document.getElementById("add").addEventListener("click", () => add("Another message"));

const quiz = components.questionnaire({
  items: [
    { name: "direction", required: true, prompt: "What should we build next?", description: "Choose a direction.", choices: [{ value: "trace", label: "Tool call timeline", description: "Show what the agent ran." }, { value: "approval", label: "Approval checkpoints" }, { value: "handoff", label: "Sub-agent handoffs" }] },
    { name: "detail", required: false, prompt: "How much detail?", description: "Skip it if you are not sure.", choices: [{ value: "focused", label: "Focused" }, { value: "complete", label: "Complete" }] },
  ],
  onSubmit: (answers) => popups.toast(JSON.stringify(answers)),
});
document.getElementById("quiz").append(quiz.element);

